#include <stdio.h>

char clasificarNota(float nota) {
    if (nota >= 90) {
        return 'A';
    } else if (nota >= 80) {
        return 'B';
    } else if (nota >= 70) {
        return 'C';
    } else if (nota >= 60) {
        return 'D';
    } else {
        return 'F';
    }
}

int main() {
    int n, i;
    float nota;
    char letra;

    printf("Cuantos estudiantes? ");
    scanf("%d", &n);

    for (i = 0; i < n; i++) {
        printf("Nota del estudiante %d: ", i + 1);
        scanf("%f", &nota);
        letra = clasificarNota(nota);
        printf("Calificacion: %c\n", letra);
    }

    return 0;
}
```

Fíjate cómo el main es el que imprime con printf, usando el valor que devuelve la función. ¿Ves la separación de responsabilidades?
